//! On-disk database of visited directories.

use std::cmp::Ordering;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};

use crate::config;
use crate::util;

pub type Rank = f64;
pub type Epoch = u64;

const VERSION: u32 = 3;
const DB_FILE: &str = "db.zo";

#[derive(Clone, Debug)]
pub struct Dir {
    pub path: String,
    pub rank: Rank,
    pub last_accessed: Epoch,
}

impl Dir {
    /// Frecency score of this directory at the given time.
    pub fn score(&self, now: Epoch) -> Rank {
        const HOUR: Epoch = 60 * 60;
        const DAY: Epoch = 24 * HOUR;
        const WEEK: Epoch = 7 * DAY;

        let duration = now.saturating_sub(self.last_accessed);
        if duration < HOUR {
            self.rank * 4.0
        } else if duration < DAY {
            self.rank * 2.0
        } else if duration < WEEK {
            self.rank / 2.0
        } else {
            self.rank / 4.0
        }
    }

    /// Score formatted for display (clamped to a 4-digit range).
    pub fn display_score(&self, now: Epoch) -> String {
        format!("{:>6.1}", self.score(now).clamp(0.0, 9999.0))
    }
}

pub struct Database {
    pub dirs: Vec<Dir>,
    pub dirty: bool,
    data_dir: PathBuf,
}

impl Database {
    pub fn open() -> Result<Database> {
        let data_dir = config::data_dir()?;
        fs::create_dir_all(&data_dir)
            .with_context(|| format!("unable to create data directory: {}", data_dir.display()))?;

        let path = data_dir.join(DB_FILE);
        let bytes = match fs::read(&path) {
            Ok(bytes) => bytes,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                return Ok(Database { dirs: Vec::new(), dirty: false, data_dir });
            }
            Err(e) => {
                return Err(e)
                    .with_context(|| format!("could not read from database: {}", path.display()));
            }
        };

        let dirs = deserialize(&bytes)?;
        Ok(Database { dirs, dirty: false, data_dir })
    }

    pub fn save(&mut self) -> Result<()> {
        if !self.dirty {
            return Ok(());
        }
        let bytes = serialize(&self.dirs);
        let path = self.data_dir.join(DB_FILE);
        write_atomic(&self.data_dir, &path, &bytes).context("could not write to database")?;
        self.dirty = false;
        Ok(())
    }

    /// Increments the rank of a directory, updating its access time. Creates the
    /// entry if it does not exist.
    pub fn add_update(&mut self, path: impl AsRef<str> + Into<String>, by: Rank, now: Epoch) {
        match self.dirs.iter_mut().find(|dir| dir.path == path.as_ref()) {
            Some(dir) => {
                dir.rank = (dir.rank + by).max(0.0);
                dir.last_accessed = now;
            }
            None => self.dirs.push(Dir { path: path.into(), rank: by.max(0.0), last_accessed: now }),
        }
        self.dirty = true;
    }

    /// Increments the rank of a directory without touching its access time.
    /// Creates the entry if it does not exist.
    pub fn add(&mut self, path: impl AsRef<str> + Into<String>, by: Rank, now: Epoch) {
        match self.dirs.iter_mut().find(|dir| dir.path == path.as_ref()) {
            Some(dir) => {
                dir.rank = (dir.rank + by).max(0.0);
            }
            None => self.dirs.push(Dir { path: path.into(), rank: by.max(0.0), last_accessed: now }),
        }
        self.dirty = true;
    }

    /// Appends a raw entry (used when importing).
    pub fn push(&mut self, path: String, rank: Rank, last_accessed: Epoch) {
        self.dirs.push(Dir { path, rank, last_accessed });
        self.dirty = true;
    }

    pub fn remove(&mut self, path: &str) -> bool {
        match self.dirs.iter().position(|dir| dir.path == path) {
            Some(idx) => {
                self.swap_remove(idx);
                true
            }
            None => false,
        }
    }

    pub fn swap_remove(&mut self, idx: usize) {
        self.dirs.swap_remove(idx);
        self.dirty = true;
    }

    /// Scales down ranks when the total exceeds `max_age`, dropping entries that
    /// become insignificant.
    pub fn age(&mut self, max_age: Rank) {
        let total: Rank = self.dirs.iter().map(|dir| dir.rank).sum();
        if total > max_age {
            let factor = 0.9 * max_age / total;
            for dir in &mut self.dirs {
                dir.rank *= factor;
            }
            self.dirs.retain(|dir| dir.rank >= 1.0);
            self.dirty = true;
        }
    }

    /// Stable sort by ascending score.
    pub fn sort_by_score(&mut self, now: Epoch) {
        self.dirs.sort_by(|a, b| a.score(now).total_cmp(&b.score(now)));
        self.dirty = true;
    }

    /// Merges entries that share the same path.
    pub fn dedup(&mut self) {
        self.dirs.sort_by(|a, b| a.path.cmp(&b.path));
        for idx in (1..self.dirs.len()).rev() {
            let (cur, prev) = (&self.dirs[idx], &self.dirs[idx - 1]);
            if cur.path == prev.path {
                let rank = cur.rank + prev.rank;
                let last_accessed = cur.last_accessed.max(prev.last_accessed);
                let prev = &mut self.dirs[idx - 1];
                prev.rank = rank;
                prev.last_accessed = last_accessed;
                self.dirs.swap_remove(idx);
            }
        }
        self.dirty = true;
    }
}

fn write_atomic(dir: &Path, dest: &Path, bytes: &[u8]) -> Result<()> {
    let tmp_name = format!("tmp_{}", util::random_alphanumeric(12));
    let tmp_path = dir.join(tmp_name);
    let mut file = fs::File::create(&tmp_path)
        .with_context(|| format!("could not create file: {}", tmp_path.display()))?;
    let result = file
        .write_all(bytes)
        .with_context(|| format!("could not write to file: {}", tmp_path.display()))
        .and_then(|()| {
            fs::rename(&tmp_path, dest).with_context(|| {
                format!("could not move file: {} -> {}", tmp_path.display(), dest.display())
            })
        });
    if result.is_err() {
        let _ = fs::remove_file(&tmp_path);
    }
    result
}

// ---------------------------------------------------------------------------
// Serialization. Little-endian, fixed-width integers; strings are length-prefixed.
// ---------------------------------------------------------------------------

fn serialize(dirs: &[Dir]) -> Vec<u8> {
    let mut out = Vec::with_capacity(4 + 8 + dirs.len() * 48);
    out.extend_from_slice(&VERSION.to_le_bytes());
    out.extend_from_slice(&(dirs.len() as u64).to_le_bytes());
    for dir in dirs {
        out.extend_from_slice(&(dir.path.len() as u64).to_le_bytes());
        out.extend_from_slice(dir.path.as_bytes());
        out.extend_from_slice(&dir.rank.to_le_bytes());
        out.extend_from_slice(&dir.last_accessed.to_le_bytes());
    }
    out
}

fn deserialize(bytes: &[u8]) -> Result<Vec<Dir>> {
    let (version, rest) = match bytes.get(..4) {
        Some(header) => (u32::from_le_bytes(header.try_into().unwrap()), &bytes[4..]),
        None => bail!("could not deserialize database: corrupted data"),
    };
    if version != VERSION {
        bail!("unsupported version (got {version}, supports {VERSION})");
    }
    decode_dirs(rest).context("could not deserialize database")
}

#[derive(Debug)]
enum DecodeError {
    UnexpectedEof,
    SliceEof,
    Utf8(std::str::Utf8Error),
    TrailingBytes,
}

impl std::fmt::Display for DecodeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DecodeError::UnexpectedEof => write!(f, "io error: unexpected end of file"),
            DecodeError::SliceEof => write!(f, "io error: "),
            DecodeError::Utf8(e) => write!(f, "string is not valid utf8: {e}"),
            DecodeError::TrailingBytes => {
                write!(f, "Slice had bytes remaining after deserialization")
            }
        }
    }
}

impl std::error::Error for DecodeError {}

struct Reader<'a> {
    bytes: &'a [u8],
}

impl<'a> Reader<'a> {
    fn fixed<const N: usize>(&mut self) -> Result<[u8; N], DecodeError> {
        if self.bytes.len() < N {
            return Err(DecodeError::UnexpectedEof);
        }
        let (head, tail) = self.bytes.split_at(N);
        self.bytes = tail;
        Ok(head.try_into().unwrap())
    }

    fn u64(&mut self) -> Result<u64, DecodeError> {
        Ok(u64::from_le_bytes(self.fixed::<8>()?))
    }

    fn f64(&mut self) -> Result<f64, DecodeError> {
        Ok(f64::from_le_bytes(self.fixed::<8>()?))
    }

    fn string(&mut self) -> Result<String, DecodeError> {
        let len = self.u64()?;
        if len > self.bytes.len() as u64 {
            return Err(DecodeError::SliceEof);
        }
        let (head, tail) = self.bytes.split_at(len as usize);
        self.bytes = tail;
        let s = std::str::from_utf8(head).map_err(DecodeError::Utf8)?;
        Ok(s.to_owned())
    }
}

fn decode_dirs(bytes: &[u8]) -> Result<Vec<Dir>, DecodeError> {
    let mut reader = Reader { bytes };
    let len = reader.u64()?;
    let capacity = usize::try_from(len).unwrap_or(usize::MAX).min(1 << 16);
    let mut dirs = Vec::with_capacity(capacity);
    for _ in 0..len {
        let path = reader.string()?;
        let rank = reader.f64()?;
        let last_accessed = reader.u64()?;
        dirs.push(Dir { path, rank, last_accessed });
    }
    if !reader.bytes.is_empty() {
        return Err(DecodeError::TrailingBytes);
    }
    Ok(dirs)
}

#[allow(dead_code)]
pub fn cmp_score(a: &Dir, b: &Dir, now: Epoch) -> Ordering {
    a.score(now).total_cmp(&b.score(now))
}
EOF
