    let mut stack: Vec<Component> = Vec::new();
    for component in components {
        match component {
            Component::RootDir => {
                stack.clear();
                stack.push(component);
            }
            Component::CurDir => {}
            Component::ParentDir => {
                if stack.len() > 1 {
                    stack.pop();
                }
            }
            Component::Normal(_) | Component::Prefix(_) => stack.push(component),
        }
    }
    let mut out = PathBuf::new();
    for component in stack {
        out.push(component.as_os_str());
    }
    out
}

