//! Interface to the fzf fuzzy finder.

use std::io::{self, BufWriter, Read, Write};
use std::process::{Child, ChildStdin, Command, Stdio};

use anyhow::{bail, Context, Result};

use crate::config;
use crate::db::{Dir, Epoch};
use crate::error::{SilentExit, FZF_ABORT_CODE};

const PREVIEW_CMD: &str = r"\command -p ls -Cp --color=always --group-directories-first {2..}";

pub struct Fzf {
    child: Child,
    stdin: Option<BufWriter<ChildStdin>>,
}

impl Fzf {
    /// Launches fzf for interactive selection in `query -i`.
    pub fn new() -> Result<Fzf> {
        let mut cmd = Command::new("fzf");
        cmd.args(["--delimiter=\t", "--nth=2", "--read0"]);
        match config::fzf_opts() {
            Some(opts) => {
                cmd.env("FZF_DEFAULT_OPTS", opts);
            }
            None => {
                cmd.args([
                    "--exact",
                    "--no-sort",
                    "--bind=ctrl-z:ignore,btab:up,tab:down",
                    "--cycle",
                    "--keep-right",
                    "--border=sharp",
                    "--height=45%",
                    "--info=inline",
                    "--layout=reverse",
                    "--tabstop=1",
                    "--exit-0",
                    &format!("--preview={PREVIEW_CMD}"),
                    "--preview-window=down,30%,sharp",
                ]);
                cmd.env("SHELL", "sh");
            }
        }
        Self::spawn(cmd)
    }

    /// Launches fzf for the interactive database editor.
    pub fn new_edit() -> Result<Fzf> {
        let mut cmd = Command::new("fzf");
        cmd.args(["--delimiter=\t", "--nth=2", "--read0"]);
        cmd.args([
            "--exact",
            "--no-sort",
            "--bind=btab:up,ctrl-r:reload(zoxide edit reload),ctrl-d:reload(zoxide edit delete {2..}),ctrl-w:reload(zoxide edit increment {2..}),ctrl-s:reload(zoxide edit decrement {2..}),ctrl-z:ignore,double-click:ignore,enter:abort,start:reload(zoxide edit reload),tab:down",
            "--cycle",
            "--keep-right",
            "--border=sharp",
            "--border-label=  zoxide-edit  ",
            "--header=ctrl-r:reload   \tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH",
            "--info=inline",
            "--layout=reverse",
            "--padding=1,0,0,0",
            "--color=label:bold",
            "--tabstop=1",
            &format!("--preview={PREVIEW_CMD}"),
            "--preview-window=down,30%,sharp",
        ]);
        cmd.env("SHELL", "sh");
        Self::spawn(cmd)
    }

    fn spawn(mut cmd: Command) -> Result<Fzf> {
        cmd.stdin(Stdio::piped()).stdout(Stdio::piped());
        let mut child = match cmd.spawn() {
            Ok(child) => child,
            Err(e) if e.kind() == io::ErrorKind::NotFound => {
                bail!("could not find fzf, is it installed?")
            }
            Err(e) => return Err(e).context("could not launch fzf"),
        };
        let stdin = child.stdin.take().map(BufWriter::new);
        Ok(Fzf { child, stdin })
    }

    /// Feeds a directory to fzf. Errors caused by fzf closing its input early
    /// are ignored.
    pub fn write(&mut self, dir: &Dir, now: Epoch) -> Result<()> {
        if let Some(stdin) = self.stdin.as_mut() {
            write_dir(stdin, dir, now)?;
        }
        Ok(())
    }

    /// Waits for fzf to exit and returns what it printed.
    pub fn select(mut self) -> Result<String> {
        // Close the input so that fzf knows there is nothing more to read.
        if let Some(mut stdin) = self.stdin.take() {
            let _ = stdin.flush();
            drop(stdin);
        }

        let mut output = String::new();
        if let Some(mut stdout) = self.child.stdout.take() {
            stdout.read_to_string(&mut output).context("failed to read from fzf")?;
        }

        let status = self.child.wait().context("wait failed on fzf")?;
        match status.code() {
            Some(0) => Ok(output),
            Some(1) => bail!("no match found"),
            Some(2) => bail!("fzf returned an error"),
            Some(code) if code == i32::from(FZF_ABORT_CODE) => {
                Err(SilentExit { code: FZF_ABORT_CODE }.into())
            }
            Some(128..=254) | None => bail!("fzf was terminated"),
            _ => bail!("fzf returned an unknown error"),
        }
    }
}

/// Writes a directory in the format understood by fzf (`score<TAB>path<NUL>`).
pub fn write_dir(writer: &mut impl Write, dir: &Dir, now: Epoch) -> Result<()> {
    let line = format!("{}\t{}\0", dir.display_score(now), dir.path);
    match writer.write_all(line.as_bytes()) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
        Err(e) => Err(e).context("could not write to fzf"),
    }
}
