        cmd.env("SHELL", "sh");
        Self::spawn(cmd)
    }

    fn spawn(mut cmd: Command) -> Result<Fzf> {
        cmd.stdin(Stdio::piped()).stdout(Stdio::piped());
        let mut child = match cmd.spawn() {
            Ok(child) => child,
            Err(e) if e.kind() == io::ErrorKind::NotFound => {
                bail!("could not find fzf, is it installed?")
            }
            Err(e) => return Err(e).context("could not launch fzf"),
        };
        let stdin = child.stdin.take().map(BufWriter::new);
        Ok(Fzf { child, stdin })
    }

    /// Feeds a directory to fzf. Errors caused by fzf closing its input early
    /// are ignored.
    pub fn write(&mut self, dir: &Dir, now: Epoch) -> Result<()> {
        if let Some(stdin) = self.stdin.as_mut() {
            write_dir(stdin, dir, now)?;
        }
        Ok(())
    }

    /// Waits for fzf to exit and returns what it printed.
    pub fn select(mut self) -> Result<String> {
        // Close the input so that fzf knows there is nothing more to read.
        if let Some(mut stdin) = self.stdin.take() {
            let _ = stdin.flush();
            drop(stdin);
        }

        let mut output = String::new();
        if let Some(mut stdout) = self.child.stdout.take() {
            stdout.read_to_string(&mut output).context("failed to read from fzf")?;
        }

        let status = self.child.wait().context("wait failed on fzf")?;
        match status.code() {
            Some(0) => Ok(output),
            Some(1) => bail!("no match found"),
            Some(2) => bail!("fzf returned an error"),
            Some(code) if code == i32::from(FZF_ABORT_CODE) => {
                Err(SilentExit { code: FZF_ABORT_CODE }.into())
            }
            Some(128..=254) | None => bail!("fzf was terminated"),
            _ => bail!("fzf returned an unknown error"),
        }
    }
}

/// Writes a directory in the format understood by fzf (`score<TAB>path<NUL>`).
pub fn write_dir(writer: &mut impl Write, dir: &Dir, now: Epoch) -> Result<()> {
    let line = format!("{}\t{}\0", dir.display_score(now), dir.path);
    match writer.write_all(line.as_bytes()) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
        Err(e) => Err(e).context("could not write to fzf"),
    }
}
