//! Lazily iterates over matching directories, highest score first.

use std::fs;
use std::path::Path;

use crate::db::{Database, Dir, Epoch};
use crate::util;

/// Entries that no longer exist on disk and have not been accessed for this
/// long are dropped from the database when encountered.
const STALE_AFTER: Epoch = 90 * 24 * 60 * 60;

pub struct Stream<'db> {
    db: &'db mut Database,
    idx_start: usize,
    now: Epoch,
    keywords: Vec<String>,
    check_exists: bool,
    resolve_symlinks: bool,
    exclude: Option<String>,
    base_dir: Option<String>,
}

impl<'db> Stream<'db> {
    pub fn new(db: &'db mut Database, now: Epoch) -> Stream<'db> {
        Stream {
            db,
            idx_start: 0,
            now,
            keywords: Vec::new(),
            check_exists: false,
            resolve_symlinks: false,
            exclude: None,
            base_dir: None,
        }
    }

    pub fn with_keywords<S: AsRef<str>>(mut self, keywords: &[S]) -> Self {
        self.keywords = keywords.iter().map(|k| util::to_lowercase(k.as_ref())).collect();
        self
    }

    pub fn with_exists(mut self, check: bool, resolve_symlinks: bool) -> Self {
        self.check_exists = check;
        self.resolve_symlinks = resolve_symlinks;
        self
    }

    pub fn with_exclude(mut self, exclude: Option<String>) -> Self {
        self.exclude = exclude;
        self
    }

    pub fn with_base_dir(mut self, base_dir: Option<String>) -> Self {
        self.base_dir = base_dir;
        self
    }

    pub fn now(&self) -> Epoch {
        self.now
    }

    pub fn next(&mut self) -> Option<&Dir> {
        while self.idx_start < self.db.dirs.len() {
            let idx = self.db.dirs.len() - self.idx_start - 1;
            let dir = &self.db.dirs[idx];

            if !self.matches_keywords(&dir.path) || !self.matches_base_dir(&dir.path) {
                self.idx_start += 1;
                continue;
            }

            if !self.exists(&dir.path) {
                if dir.last_accessed < self.now.saturating_sub(STALE_AFTER) {
                    self.db.swap_remove(idx);
                } else {
                    self.idx_start += 1;
                }
                continue;
            }

            if self.exclude.as_deref() == Some(dir.path.as_str()) {
                self.idx_start += 1;
                continue;
            }

            self.idx_start += 1;
            return Some(&self.db.dirs[idx]);
        }
        None
    }

    fn matches_keywords(&self, path: &str) -> bool {
        let (last, rest) = match self.keywords.split_last() {
            Some(split) => split,
            None => return true,
        };

        let path = util::to_lowercase(path);
        let mut path = path.as_str();

        match path.rfind(last.as_str()) {
            Some(idx) => {
                if path[idx + last.len()..].contains('/') {
                    return false;
                }
                path = &path[..idx];
            }
            None => return false,
        }

        for keyword in rest.iter().rev() {
            match path.rfind(keyword.as_str()) {
                Some(idx) => path = &path[..idx],
                None => return false,
            }
        }
        true
    }

    fn matches_base_dir(&self, path: &str) -> bool {
        match &self.base_dir {
            Some(base_dir) => Path::new(path).starts_with(base_dir),
            None => true,
        }
    }

    fn exists(&self, path: &str) -> bool {
        if !self.check_exists {
            return true;
        }
        // When symlinks are resolved on insertion, a stored symlink is treated
        // as missing so that it gets replaced by its target.
        let metadata = if self.resolve_symlinks {
            fs::symlink_metadata(path)
        } else {
            fs::metadata(path)
        };
        metadata.map(|m| m.is_dir()).unwrap_or(false)
    }
}
