        let mut db = Database::open()?;
        let result = self.query(&mut db);
        let saved = db.save();
        result.and(saved)
    }

    fn query(&self, db: &mut Database) -> Result<()> {
        let now = util::current_time()?;
        db.sort_by_score(now);

        let mut stream = Stream::new(db, now)
            .with_keywords(&self.keywords)
            .with_exists(!self.all, config::resolve_symlinks())
            .with_exclude(self.exclude.clone())
            .with_base_dir(self.base_dir.clone());

        if self.interactive {
            let mut fzf = Fzf::new()?;
            while let Some(dir) = stream.next() {
                fzf.write(dir, now)?;
            }
            let selection = fzf.select()?;
            if self.score {
                print!("{selection}");
            } else {
                let path = selection.get(7..).context("could not read selection from fzf")?;
                print!("{path}");
            }
        } else if self.list {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            while let Some(dir) = stream.next() {
                write_entry(&mut handle, dir, now, self.score)?;
            }
        } else {
            let dir = stream.next().context("no match found")?;
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            write_entry(&mut handle, dir, now, self.score)?;
        }
        Ok(())
    }
}

fn write_entry(
    out: &mut impl Write,
    dir: &crate::db::Dir,
    now: crate::db::Epoch,
    with_score: bool,
) -> Result<()> {
    let result = if with_score {
        writeln!(out, "{} {}", dir.display_score(now), dir.path)
    } else {
        writeln!(out, "{}", dir.path)
    };
    result.context("could not write to stdout")
}
