//! Command-line interface definition and dispatch.

use std::path::PathBuf;

use anyhow::Result;
use clap::builder::PossibleValuesParser;
use clap::{value_parser, Arg, ArgAction, ArgMatches, Command};

use crate::cmd::add::Add;
use crate::cmd::edit::Edit;
use crate::cmd::import::{Import, ImportFrom};
use crate::cmd::init::Init;
use crate::cmd::query::Query;
use crate::cmd::remove::Remove;
use crate::config;
use crate::shell::{Hook, Shell};

const VERSION: &str = "0.9.9";
const AUTHOR: &str = "Ajeet D'Souza <98ajeet@gmail.com>";

const HELP_TEMPLATE: &str = "\
{before-help}{name} {version}
{author}
https://github.com/ajeetdsouza/zoxide

{about}

Usage:
  {usage}

{all-args}{after-help}";

const ENV_HELP: &str = "\
Environment variables:
  _ZO_DATA_DIR          Path for zoxide data files
  _ZO_ECHO              Print the matched directory before navigating to it when set to 1
  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded
  _ZO_FZF_OPTS          Custom flags to pass to fzf
  _ZO_MAXAGE            Maximum total age after which entries start getting deleted
  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths";

fn styled(cmd: Command) -> Command {
    cmd.help_template(HELP_TEMPLATE).after_help(ENV_HELP)
}

pub fn build() -> Command {
    let add = styled(Command::new("add"))
        .about("Add a new directory or increment its rank")
        .arg(
            Arg::new("paths")
                .value_name("PATHS")
                .required(true)
                .num_args(1..)
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("score")
                .short('s')
                .long("score")
                .value_name("SCORE")
                .help("The rank to increment the entry if it exists or initialize it with if it doesn't")
                .value_parser(value_parser!(f64)),
        );

    let edit = styled(Command::new("edit"))
        .about("Edit the database")
        .subcommand(Command::new("reload").hide(true))
        .subcommand(
            Command::new("delete")
                .hide(true)
                .arg(Arg::new("path").value_name("PATH").required(true)),
        )
        .subcommand(
            Command::new("increment")
                .hide(true)
                .arg(Arg::new("path").value_name("PATH").required(true)),
        )
        .subcommand(
            Command::new("decrement")
                .hide(true)
                .arg(Arg::new("path").value_name("PATH").required(true)),
        );

    let import = styled(Command::new("import"))
        .about("Import entries from another application")
        .arg(
            Arg::new("path")
                .value_name("PATH")
                .required(true)
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("from")
                .long("from")
                .value_name("FROM")
                .help("Application to import from")
                .required(true)
                .value_parser(PossibleValuesParser::new(["autojump", "z"])),
        )
        .arg(
            Arg::new("merge")
                .long("merge")
                .help("Merge into existing database")
                .action(ArgAction::SetTrue),
        );

    let init = styled(Command::new("init"))
        .about("Generate shell configuration")
        .arg(
            Arg::new("shell")
                .value_name("SHELL")
                .required(true)
                .value_parser(PossibleValuesParser::new([
                    "bash",
                    "elvish",
                    "fish",
                    "nushell",
                    "posix",
                    "powershell",
                    "tcsh",
                    "xonsh",
                    "zsh",
                ])),
        )
        .arg(
            Arg::new("no_cmd")
                .long("no-cmd")
                .help("Prevents zoxide from defining the `z` and `zi` commands")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("cmd")
                .long("cmd")
                .value_name("CMD")
                .help("Changes the prefix of the `z` and `zi` commands")
                .default_value("z"),
        )
        .arg(
            Arg::new("hook")
                .long("hook")
