cat > src/dirs.rs <<'EOF'
//! Locating well-known user directories without pulling in extra crates.

use std::env;
use std::ffi::{CStr, OsString};
use std::os::unix::ffi::OsStringExt;
use std::path::PathBuf;

/// The user's home directory: `$HOME` when set and non-empty, otherwise the
/// entry from the password database.
pub fn home_dir() -> Option<PathBuf> {
    env::var_os("HOME")
        .filter(|h| !h.is_empty())
        .or_else(passwd_home)
        .map(PathBuf::from)
}

/// Directory for user-specific data files, following the XDG specification:
/// `$XDG_DATA_HOME` when it is an absolute path, else `$HOME/.local/share`.
pub fn data_local_dir() -> Option<PathBuf> {
    if let Some(dir) = env::var_os("XDG_DATA_HOME") {
        let dir = PathBuf::from(dir);
        if dir.is_absolute() {
            return Some(dir);
        }
    }
    home_dir().map(|home| home.join(".local/share"))
}

#[repr(C)]
struct Passwd {
    pw_name: *mut libc_char,
    pw_passwd: *mut libc_char,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *mut libc_char,
    pw_dir: *mut libc_char,
    pw_shell: *mut libc_char,
}

#[allow(non_camel_case_types)]
type libc_char = std::os::raw::c_char;

extern "C" {
    fn getuid() -> u32;
    fn getpwuid_r(
        uid: u32,
        pwd: *mut Passwd,
        buf: *mut libc_char,
        buflen: usize,
        result: *mut *mut Passwd,
    ) -> i32;
}

fn passwd_home() -> Option<OsString> {
    let mut buf = vec![0 as libc_char; 16 * 1024];
    let mut passwd = std::mem::MaybeUninit::<Passwd>::uninit();
    let mut result: *mut Passwd = std::ptr::null_mut();
    // SAFETY: all pointers refer to live, properly sized local buffers, and the
    // struct layout matches glibc's `struct passwd` on Linux.
    let rc = unsafe {
        getpwuid_r(getuid(), passwd.as_mut_ptr(), buf.as_mut_ptr(), buf.len(), &mut result)
    };
    if rc != 0 || result.is_null() {
        return None;
    }
    // SAFETY: `result` is non-null and points at the initialized struct.
    let dir_ptr = unsafe { (*result).pw_dir };
    if dir_ptr.is_null() {
        return None;
    }
    // SAFETY: `pw_dir` is a NUL-terminated string within `buf`.
    let bytes = unsafe { CStr::from_ptr(dir_ptr) }.to_bytes();
    if bytes.is_empty() {
        return None;
    }
    Some(OsString::from_vec(bytes.to_vec()))
}
EOF
